    if clues:
        # Search small periods, requiring matching colors on congruent diagonals.
        for p in range(1, max(h, w) + 1):
            residues = {}
            ok = True
            for d, color in clues.items():
                k = d % p
                if k in residues and residues[k] != color:
                    ok = False
                    break
                residues[k] = color
            if ok and len(residues) == p:
                # Fill full grid with periodic diagonal pattern.
                return [[residues[(c-r) % p] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
